package com.example.library.loan;

import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;
import org.springframework.data.repository.query.Param;

public interface LoanRepository extends JpaRepository<Loan, Long> {

    long countByMemberIdAndReturnedAtIsNull(String memberId);

    boolean existsByIsbnAndReturnedAtIsNull(String isbn);

    // Serializes concurrent borrows by the same member for the duration of the transaction.
    @Query(value = "SELECT pg_advisory_xact_lock(hashtext(:memberId))", nativeQuery = true)
    void lockMember(@Param("memberId") String memberId);
}
