package com.example.library.loan;

import java.time.Instant;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class LoanService {

    static final int MAX_LOANS_PER_MEMBER = 3;

    private final LoanRepository loans;

    public LoanService(LoanRepository loans) {
        this.loans = loans;
    }

    @Transactional
    public Loan borrow(String memberId, String isbn) {
        loans.lockMember(memberId);
        if (loans.countByMemberIdAndReturnedAtIsNull(memberId) >= MAX_LOANS_PER_MEMBER) {
            throw new LoanRejectedException("Member " + memberId + " already has "
                    + MAX_LOANS_PER_MEMBER + " active loans");
        }
        if (loans.existsByIsbnAndReturnedAtIsNull(isbn)) {
            throw new LoanRejectedException("Book " + isbn + " is already on loan");
        }
        try {
            return loans.saveAndFlush(new Loan(memberId, isbn, Instant.now()));
        } catch (DataIntegrityViolationException e) {
            // Another member borrowed the same book concurrently (unique partial index).
            throw new LoanRejectedException("Book " + isbn + " is already on loan");
        }
    }
}
